def H(type_, hours, closed, best, stay, cost, tip, alt="", verify=(), tickets=None):
    d = {"type": type_, "hours": hours, "closedNote": closed, "bestTime": best, "stay": stay, "cost": cost,
         "tip": tip, "weatherAlt": alt, "verify": list(verify)}
